const rttMs = 100; // round-trip time in ms; try 150 for an Asia-US path
const handshakes = {
  'QUIC 1-RTT (new)':      1,
  'QUIC 0-RTT (resume)':   0,
  'TCP+TLS 1.3 (new)':     2, // 1 RTT TCP + 1 RTT TLS 1.3
  'TCP+TLS 1.2 (new)':     3, // 1 RTT TCP + 2 RTT TLS 1.2
};
for (const [name, rtts] of Object.entries(handshakes)) {
  console.log(`${name}: ${rtts} RTT = ${rtts * rttMs} ms to first app byte`);
}
const saved = (handshakes['TCP+TLS 1.3 (new)'] - handshakes['QUIC 1-RTT (new)']) * rttMs;
console.log(`QUIC saves ${saved} ms vs TCP+TLS 1.3 on this link`);
